def sum_of_digits(numbers):
    def compute_digit_sum(num):
        # Ensure num is an integer and compute its digit sum
        if isinstance(num, int):
            return sum(int(digit) for digit in str(abs(num)))  # Handle negative numbers with abs()
        return 0  # Ignore non-integer elements

    def flatten(lst):
        # Recursively flatten the list
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    # Flatten the input list and compute the total sum of digits
    return sum(compute_digit_sum(num) for num in flatten(numbers))

# Example usage with test cases:
assert sum_of_digits([10, 2, 56]) == 14
assert sum_of_digits([[10, 20, 4, 5, 'b', 70, 'a']]) == 19
assert sum_of_digits([[-10, 15, [32, 'x'], 50]]) == 16
assert sum_of_digits(['a', 'b', 123]) == 6
assert sum_of_digits([]) == 0
